using Value=VALUE_TYPE;
int main(int argc,char**argv){if(argc!=4)return 2;std::size_t n=std::strtoull(argv[1],nullptr,10);int mode=std::atoi(argv[2]);bool strict=std::atoi(argv[3]);std::vector<Value>a(n);std::mt19937_64 rng(789956);
 for(std::size_t i=0;i<n;++i){Value x{};switch(mode){case 0:x=Value(rng()%1000000000);break;case 1:x=Value(i);break;case 2:x=Value(n-i);break;case 3:x=0;break;case 4:x=Value(rng()%2);break;case 5:x=Value(rng()%16);break;case 6:x=Value(rng()%256);break;case 7:x=Value(i%512);break;case 8:x=Value(i&1? n-i:i);break;case 9:x=i<256?Value(rng()%1000000000):Value(1000000000+i);break;case 10:x=i<n/2?Value(rng()%1000000000):-Value(i);break;}a[i]=x;}
 const auto original=a;const int reps=(mode==1||mode==2||mode==3?8:1)*std::max(std::size_t{1},std::size_t{131072}/std::max(std::size_t{1},n));std::uint64_t checksum=0;
 auto run=[&]<bool Strict>(){
#if OP == 0
 auto r=LISIndices<Strict>(a);if(r.size()){checksum+=r.size()+r.front()+r.back();}
#elif OP == 1
 checksum+=LISLength<Strict>(a);
#elif OP == 2
