            count = before ? count - half - 1 : half;
        }
        } else
#endif
        while (count != 0) {
            const auto half = count / 2;
            const auto mid = lo + half;
            const bool before = Strict ? values[mid] < v[i] : !(v[i] < values[mid]);
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
