#!/usr/bin/env python3
"""Freeze one LIS candidate and run the requested correctness matrix on CPU4."""
import os
os.sched_setaffinity(0, {4})
import argparse
import datetime
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys

BASE = Path(__file__).resolve().parent
REPO = Path('/home/reinsirk/Atcoder_Env')
COMPILERS = {
    'gcc152': ['/usr/bin/g++'],
    'clang': ['clang++', '--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],
    'gcc153': ['/usr/local/bin/g++'],
}

def digest(data):
    return hashlib.sha256(data).hexdigest()

def file_hash(path):
    return digest(path.read_bytes())

def execute(command, **kwargs):
    return subprocess.run(['taskset', '-c', '4', *command], capture_output=True, text=True, **kwargs)

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', required=True, type=Path)
    parser.add_argument('--expected-sha256')
    parser.add_argument('--label', default='selected')
    parser.add_argument('--baseline', type=Path)
    parser.add_argument('--expected-baseline-sha256')
    parser.add_argument('--with-generic', action='store_true', help='Add the independent generic supplement (48 rather than 36 configurations).')
    parser.add_argument('--generic-fixture', type=Path, default=BASE/'lis_generic_search_reference.cpp')
    parser.add_argument('--output-root', type=Path, default=BASE/'final_matrix')
    args = parser.parse_args()
    source = args.source.resolve()
    data = source.read_bytes()
    source_sha = digest(data)
    if args.expected_sha256 and source_sha != args.expected_sha256:
        raise SystemExit('Requested source hash does not match --expected-sha256')
    fixtures = [REPO/'Verify/current/tests'/name for name in (
        'lis_reference_test.cpp', 'lis_cache_reference_test.cpp', 'lis_exception_test.cpp')]
    fixtures.append(BASE/'lis_simd_phase_reference_test.cpp')
    if args.with_generic:
        fixtures.append(args.generic_fixture.resolve())
    fixture_data = {str(path): path.read_bytes() for path in fixtures}
    bundle = digest(b''.join(path.name.encode()+b'\0'+fixture_data[str(path)] for path in fixtures))
    label = re.sub(r'[^A-Za-z0-9_.-]+', '_', args.label)
    run_dir = args.output_root.resolve()/f'{label}-{source_sha[:12]}-{bundle[:8]}'
    run_dir.mkdir(parents=True, exist_ok=True)
    header = run_dir/'library.hpp'
    if header.exists() and header.read_bytes() != data:
        raise SystemExit('Existing snapshot differs; refusing to overwrite')
    header.write_bytes(data)
    manifest = []
    fixture_dir = run_dir/'fixtures'
    fixture_dir.mkdir(exist_ok=True)
    for path in fixtures:
        frozen = fixture_dir/path.name
        frozen.write_bytes(fixture_data[str(path)])
        manifest.append({'origin': str(path), 'snapshot': str(frozen), 'sha256': file_hash(frozen)})
    report_path = run_dir/'checks.json'
    versions = {}
    for cc, compiler in COMPILERS.items():
        command = ['taskset', '-c', '4', *compiler, '--version']
        result = execute([*compiler, '--version'])
        if result.returncode or result.stderr:
            raise SystemExit(f'Compiler version check failed: {command}: {result.stderr}')
        versions[cc] = {'command': command, 'version': result.stdout.splitlines()[0]}
    if report_path.exists():
        report = json.loads(report_path.read_text())
        if report['source_sha256'] != source_sha or report['fixtures'] != manifest or report['compilers'] != versions:
            raise SystemExit('Existing report manifest differs; refusing stale resume')
    else:
        report = {'source': str(source), 'source_sha256': source_sha, 'snapshot': str(header),
                  'label': args.label, 'affinity': [4], 'fixtures': manifest, 'compilers': versions,
                  'created_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  'status': 'running', 'results': []}
    def save():
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2))
    configs = []
    for mode, flags in [('default', []), ('native', ['-march=native'])]:
        for cc in ['gcc152', 'clang']:
            for skip in [False, True]:
                for fixture in manifest:
                    configs.append((cc, mode, flags, skip, fixture))
    for mode, flags in [('disabled_default', ['-DSIRKIT_DISABLE_SIMD']), ('disabled_native', ['-DSIRKIT_DISABLE_SIMD', '-march=native'])]:
        for skip in [False, True]:
            for fixture in manifest:
                configs.append(('gcc152', mode, flags, skip, fixture))
    for skip in [False, True]:
        for fixture in manifest:
            configs.append(('gcc153', 'default', [], skip, fixture))
    for skip in [False, True]:
        for fixture in manifest:
            configs.append(('gcc152', 'asan_ubsan', ['-g', '-fsanitize=address,undefined', '-fno-omit-frame-pointer'], skip, fixture))
    report['expected_configurations'] = len(configs)
    report['status'] = 'running'
    save()
    print('REPORT', report_path, 'SOURCE', source_sha, 'CONFIGURATIONS', len(configs), flush=True)
    environment = dict(os.environ, ASAN_OPTIONS='detect_leaks=0', UBSAN_OPTIONS='halt_on_error=1')
    for cc, mode, flags, skip, fixture in configs:
        key = f"{cc}/{mode}/{int(skip)}/{Path(fixture['snapshot']).stem}"
        source_fixture = Path(fixture['snapshot'])
        executable = run_dir/key.replace('/', '-')
        command = ['taskset', '-c', '4', *COMPILERS[cc], '-std=c++23', '-O2', *flags,
                   *(['-DSKIP_RUNTIME_CHECKS'] if skip else []), f'-DSIRKIT_LIS_SOURCE="{header}"',
                   str(source_fixture), '-o', str(executable)]
        old = next((row for row in report['results'] if row['key'] == key), None)
        if old and old['passed'] and old['compile_command'] == command and old['source_sha256'] == source_sha:
            print('REUSE', key, flush=True)
            continue
        report['results'] = [row for row in report['results'] if row['key'] != key]
        build = execute(command[3:])
        row = {'key': key, 'compiler': cc, 'mode': mode, 'skip': skip,
               'source_sha256': source_sha, 'fixture_sha256': fixture['sha256'],
               'compile_command': command, 'compile_returncode': build.returncode,
               'compile_stdout': build.stdout, 'compile_stderr': build.stderr, 'passed': False}
        if build.returncode == 0 and not build.stderr:
            run_command = ['taskset', '-c', '4', str(executable)]
            try:
                result = execute([str(executable)], env=environment, timeout=300)
                row.update({'run_command': run_command, 'run_environment': {'ASAN_OPTIONS': 'detect_leaks=0', 'UBSAN_OPTIONS': 'halt_on_error=1'},
                            'returncode': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr,
                            'passed': result.returncode == 0 and not result.stderr})
            except subprocess.TimeoutExpired as error:
                row.update({'run_command': run_command, 'timeout': True, 'stdout': str(error.stdout), 'stderr': str(error.stderr)})
        report['results'].append(row)
        save()
        if not row['passed']:
            report['status'] = 'failed'
            save()
            raise SystemExit(f'Correctness check failed; full diagnostics: {report_path}: {key}')
        print('PASS', key, row['stdout'].strip(), flush=True)
    if args.baseline:
        baseline = args.baseline.resolve()
        baseline_sha = file_hash(baseline)
        if args.expected_baseline_sha256 and baseline_sha != args.expected_baseline_sha256:
            raise SystemExit('Baseline hash mismatch')
        frozen_baseline = run_dir/'baseline.hpp'
        frozen_baseline.write_bytes(baseline.read_bytes())
        proof = []
        for cc, proof_flags in [('clang', []), ('gcc153', []), ('gcc152', ['-DSIRKIT_DISABLE_SIMD'])]:
            for skip in [False, True]:
                texts = []
                for path in [header, frozen_baseline]:
                    command = [*COMPILERS[cc], '-std=c++23', *proof_flags, *(['-DSKIP_RUNTIME_CHECKS'] if skip else []), '-E', '-P', '-x', 'c++', str(path)]
                    result = execute(command)
                    if result.returncode or result.stderr:
                        raise SystemExit(f'Preprocessing failed: {command}: {result.stderr}')
                    normalized = re.sub(r'\s+', '', result.stdout)
                    texts.append(normalized)
                    proof.append({'compiler': cc, 'skip': skip, 'header': str(path),
                                  'command': ['taskset', '-c', '4', *command], 'normalized_sha256': digest(normalized.encode())})
                if texts[0] != texts[1]:
                    report['status'] = 'fallback_difference'
                    report['fallback_proof'] = proof
                    save()
                    raise SystemExit(f'Fallback preprocessing differs; see {report_path}')
        report['fallback_proof'] = {'identical': True, 'baseline_origin': str(baseline), 'baseline_sha256': baseline_sha, 'results': proof}
    if file_hash(header) != source_sha or file_hash(source) != source_sha:
        raise SystemExit('Candidate changed during matrix')
    if len(report['results']) != len(configs) or not all(row['passed'] for row in report['results']):
        raise SystemExit('Incomplete matrix')
    report['status'] = 'passed'
    save()
    print('ALL PASS', len(configs), source_sha, 'REPORT', report_path, flush=True)

if __name__ == '__main__':
    main()

